// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    keepMyEther c;
    Attacker attacker;

    function setUp() public { c = new keepMyEther(); attacker = new Attacker(c); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 1 ether);
        vm.deal(address(attacker), 2 * amount);
        attacker.deposit(amount);
        attacker.attack();
        // Reference: outer withdraw sends `amount` to caller (nested withdraw reverts
        // on the reentrancy lock and is ignored by the caller), so the attacker ends
        // up holding deposit + withdrawal = 2*amount.
        // Mutant: balances zeroed before the send, so the send transfers 0 wei and
        // the attacker only ever receives its deposit = amount != 2*amount.
        assertTrue(address(attacker).balance == 2 * amount);
    }
}

contract Attacker {
    keepMyEther c;
    bool entered;

    constructor(keepMyEther _c) { c = _c; }

    function deposit(uint256 amount) external payable {
        (bool ok, ) = address(c).call{value: amount}("");
        require(ok);
    }

    function attack() external {
        entered = false;
        c.withdraw();
    }

    receive() external payable {
        if (!entered) {
            entered = true;
            (bool ok, ) = address(c).call("");
            ok; // ignore nested revert (reentrancy lock in the reference)
        }
    }
}
